  gkyl_rect_grid_init(&g1, 2, lower, upper, cells);
  gkyl_rect_grid_init(&g2, 2, lower, upper, cells);
  TEST_CHECK( gkyl_rect_grid_cmp(&g1, &g2) );

  int cells2[] = { 4, 8 };
  gkyl_rect_grid_init(&g3, 2, lower, upper, cells2);
  TEST_CHECK( !gkyl_rect_grid_cmp(&g1, &g3) );
}

